package ch.local.autoscroll;
import android.accessibilityservice.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;
public class ScrollService extends AccessibilityService {
 final Handler h=new Handler(Looper.getMainLooper()); WindowManager wm; LinearLayout panel; Button main,stop; boolean running=false,paused=false,busy=false; long deadline,remaining,ready; int generation=0; static final String TARGET="ch.ricardo.android";
 final Runnable tick=()->step();
 int cfg(String k,int def){return getSharedPreferences("cfg",0).getInt(k,def);}
 boolean target(){AccessibilityNodeInfo n=getRootInActiveWindow();if(n==null)return false;try{return TARGET.contentEquals(n.getPackageName());}finally{n.recycle();}}
 void finish(){generation++;running=false;paused=false;h.removeCallbacks(tick);if(main!=null)main.setText("Start");}
 @Override protected void onServiceConnected(){wm=getSystemService(WindowManager.class);panel=new LinearLayout(this);main=new Button(this);main.setText("Start");stop=new Button(this);stop.setText("Stop");panel.addView(main);panel.addView(stop);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.RIGHT;lp.y=100;wm.addView(panel,lp);panel.setVisibility(View.GONE);main.setOnClickListener(v->{if(!target())return;long now=SystemClock.elapsedRealtime();if(!running){running=true;paused=false;generation++;remaining=new int[]{30,60,90,120,180}[cfg("duration",2)]*1000L;ready=now+new int[]{3,5,10}[cfg("count",1)]*1000L;deadline=ready+remaining;main.setText("Pause");h.post(tick);}else if(!paused){remaining=Math.max(0,deadline-Math.max(now,ready));paused=true;generation++;h.removeCallbacks(tick);main.setText("Resume");}else{paused=false;generation++;ready=now+1000;deadline=ready+remaining;main.setText("Pause");h.post(tick);}});stop.setOnClickListener(v->finish());}
 @Override public void onAccessibilityEvent(AccessibilityEvent e){if(panel==null)return;boolean ok=target();panel.setVisibility(ok?View.VISIBLE:View.GONE);if(!ok&&running)finish();}
 void step(){if(!running||paused)return;if(!target()){finish();return;}long now=SystemClock.elapsedRealtime();if(now>=deadline){finish();return;}if(now<ready){main.setText("Pause "+((ready-now+999)/1000));h.postDelayed(tick,200);return;}main.setText("Pause "+((deadline-now+999)/1000));if(busy){h.postDelayed(tick,100);return;}Rect r=new Rect();AccessibilityNodeInfo n=getRootInActiveWindow();if(n==null){finish();return;}n.getBoundsInScreen(r);n.recycle();if(r.width()<100||r.height()<300){finish();return;}float top=r.top+r.height()*.10f,bottom=r.bottom-r.height()*.12f;float overlap=new int[]{15,20,25}[cfg("overlap",1)]/100f;float end=bottom-(bottom-top)*(1-overlap);int ms=new int[]{600,800,1000,1500}[cfg("speed",1)];if(deadline-now<ms){h.postDelayed(tick,deadline-now);return;}Path path=new Path();path.moveTo(r.left+r.width()*.45f,bottom);path.lineTo(r.left+r.width()*.45f,end);int token=generation;busy=true;boolean sent=dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,ms)).build(),new GestureResultCallback(){public void onCompleted(GestureDescription g){busy=false;if(token==generation&&running&&!paused)h.postDelayed(tick,cfg("mode",0)==0?new int[]{1500,2500,4000,6000}[cfg("pause",1)]:350);}public void onCancelled(GestureDescription g){busy=false;if(token==generation)finish();}},null);if(!sent){busy=false;finish();}}
 @Override public void onInterrupt(){finish();} @Override public void onDestroy(){finish();if(panel!=null)wm.removeView(panel);super.onDestroy();}
}